def dualQuadraticIntegral (A : RegularHilbert H →L[ℂ] RegularHilbert H)
    (v : RegularHilbert H) : ℝ≥0∞ :=
  ENNReal.ofReal dualHaarFactor * ∫⁻ s : ℝ, dualQuadraticIntegrand A v s

def regularUnitary (P : SiteProfile) (t : ℝ) :
    RegularHilbert (TowerHilbert P) →L[ℂ] RegularHilbert (TowerHilbert P) :=
  fibre (modularFlowCLM P t) * shift t

def rhoMatInv (P : SiteProfile) (N : ℕ) :
    Matrix (chainIdx N) (chainIdx N) ℂ :=
  Matrix.diagonal (fun k => (((towerW P N k)⁻¹ : ℝ) : ℂ))

theorem factor_right_apply {x : TowerHilbert P →L[ℂ] TowerHilbert P}
    (hx : x ∈ theFactorObject P) {N : ℕ}
    (b : Matrix (chainIdx N) (chainIdx N) ℂ) (v : TowerHilbert P) :
    x (rTowerPi P b v) = rTowerPi P b (x v) :=
  congrArg (fun T : TowerHilbert P →L[ℂ] TowerHilbert P => T v) (factor_comm_rTowerPi hx b)

def regularPositiveGenerator (P : SiteProfile) :
    RegularHilbert (TowerHilbert P) →ₗ.[ℂ] RegularHilbert (TowerHilbert P) :=
  resolventGraphOperator (regularSpectralResolvent P) (regularSpectralResolvent_injective P)
